// Rich per-symbol descriptions (3-4 sentences) used by /symbol/[slug]/page.tsx
// to replace the 1-sentence fallback in symbols.ts with indexable, substantive content.
// Keys are symbol IDs from symbols.ts. Add new entries here; don't edit symbols.ts descriptions.

export const richDescriptions: Record<string, string> = {

  // ── ARROWS ──────────────────────────────────────────────────────────────────

  "right-arrow": "The right arrow (→) is one of typography's most versatile symbols, pointing the way for navigation menus, process steps, and logical implications in mathematics and computing. In formal logic it denotes implication — 'A → B' reads 'if A then B' — and in category theory it represents a morphism between objects. Web developers reach for the HTML entity &rarr; or the CSS value \\2192 when they need it programmatically. On Windows, hold Alt and type 26 on the numeric keypad to insert it.",

  "left-arrow": "The left arrow (←) signals backward navigation, undo operations, and reverse flow in everything from browser back buttons to terminal prompts. In formal logic ← can express converse implication, and in physics it labels forces or velocity vectors pointing left. The HTML entity &larr; works across email clients and web pages without any font dependency. Press Alt+27 on the Windows numeric keypad to type it.",

  "up-arrow": "The up arrow (↑) universally signals increase, improvement, upward movement, and scrolling — making it essential for dashboards, trend charts, and stock-market displays. In version-control tools it indicates pushing changes to a remote server, while in gaming it often represents a jump or climb action. The HTML entity &uarr; works in any Unicode-supporting context without special fonts. Copy it for slide decks, data tables, and social media posts showing positive trends.",

  "down-arrow": "The down arrow (↓) indicates decrease, downward scrolling, download actions, and falling trends across digital and print media. Dashboard widgets, data tables, and weather apps routinely use ↓ to communicate declining values at a glance. In terminal environments it scrolls through command history, and in spreadsheets it advances cell selection downward. Insert it with the HTML entity &darr; or the Unicode code point U+2193.",

  "left-right-arrow": "The left-right arrow (↔) symbolises bidirectional flow, logical equivalence, and horizontal resizing affordances in user interfaces. In formal logic and linguistics it represents 'if and only if' (iff), the biconditional connective. UI designers use it as the resize cursor on the horizontal axis, and chemistry educators draw it to show reversible reactions. The HTML entity is &harr; and the Unicode code point is U+2194.",

  "up-down-arrow": "The up-down arrow (↕) conveys vertical bidirectional movement, height adjustment, and the draggable resize affordance in desktop applications. In elevator controls and floor-selection displays it signals that a lift travels in both directions. Scientists also use ↕ to denote electric dipole moments aligned along a vertical axis. Use it in diagrams with the HTML entity &#8597; or copy-paste it directly.",

  "ne-arrow": "The north-east arrow (↗) signals upward trends, external links opening in a new tab, and diagonal upper-right direction in charts and maps. Analytics dashboards and financial reports rely on ↗ to celebrate positive growth at a glance. Web designers often place it beside links that leave the current site, warning users they are navigating away. It encodes as Unicode U+2197 and HTML &#8599;.",

  "se-arrow": "The south-east arrow (↘) indicates downward trends, lower-right direction, and decline in charts and dashboards. It also appears in window-resize handles in desktop operating systems — drag the lower-right corner toward that direction to enlarge a window. Traffic and weather maps use it to show movement on that compass bearing. HTML entity: &#8600;, Unicode: U+2198.",

  "sw-arrow": "The south-west arrow (↙) points to the lower-left and is used in maps for south-west compass bearings, in diagrams to show diagonal flow in that direction, and in some UI frameworks as a 'snap to lower-left corner' gesture. Its compact, angled form makes it ideal for annotating charts without interrupting the data flow. HTML entity: &#8601;, Unicode: U+2199.",

  "nw-arrow": "The north-west arrow (↖) points upper-left, appearing in maps for north-west bearings, image editors as the pointer cursor shape, and network diagrams labelling traffic flowing toward the north-west node. Combine several diagonal arrows to build compass roses for custom maps and navigation illustrations. HTML entity: &#8598;, Unicode: U+2196.",

  "double-right-arrow": "The double right arrow (⇒) is the standard symbol for logical implication in mathematics and formal logic — 'A ⇒ B' reads 'A implies B'. Computer science uses it for type-inference rules, rewriting systems, and reduction steps in programming-language theory. Unlike the plain → arrow, the double stroke specifically conveys 'therefore' or 'it necessarily follows that'. HTML entity: &rArr;, Unicode: U+21D2.",

  "double-left-arrow": "The double left arrow (⇐) represents reverse or converse implication in logic — 'B ⇐ A' means A implies B, written from the conclusion's perspective. In rewriting-rule notation it marks backward derivations, and in some keyboard layouts it labels the Backspace key. Pair it with ⇒ to construct bidirectional logical proofs on paper or in digital documents. HTML entity: &lArr;, Unicode: U+21D0.",

  "double-lr-arrow": "The double left-right arrow (⇔) denotes logical equivalence — both sides mutually imply each other, read as 'if and only if' (iff) in formal proofs and mathematics textbooks. In type theory it marks isomorphisms between types, and in algebra it signals that two equations are equivalent. It is the precise, formal cousin of ↔, reserved for strict logical biconditionals. HTML entity: &hArr;, Unicode: U+21D4.",

  "fat-right-arrow": "The heavy right arrow (➔) is a bolder, more visually dominant variant of the standard right arrow, designed to grab attention in bullet lists, call-to-action labels, and step-by-step guides. Its thick stroke remains legible at small sizes and in low-contrast print. Presenters and marketers favour ➔ to highlight transitions between key sections or slides. Unicode: U+2794, HTML: &#10132;.",

  "curved-right": "The curved right arrow (↷) arcs clockwise to indicate rotation, redo operations, and forward cycling through a sequence of items. Most desktop operating systems depict a similar clockwise arc as the 'redo last action' icon in toolbars. In board games and sports diagrams it shows a player or piece turning clockwise. HTML entity: &#8631;, Unicode: U+21B7.",

  "curved-left": "The curved left arrow (↶) arcs counter-clockwise, universally recognised as the 'undo' icon in word processors, graphic editors, and email clients worldwide. In scientific diagrams it indicates anti-clockwise rotation of a particle or mechanical component. Undo and redo arrows (↶ ↷) are displayed as a standard pair in most editing toolbars. HTML entity: &#8630;, Unicode: U+21B6.",

  "return-arrow": "The return arrow (↵) represents the carriage-return or Enter key, tracing back to the mechanical action of a typewriter's carriage returning to the start of a new line. It appears on physical keycaps, in keyboard-shortcut documentation, and in text editors to mark explicit line endings. Combine it with ⌘ in documentation to write Mac shortcuts like ⌘↵ (Command+Return). HTML entity: &#8629;, Unicode: U+21B5.",

  "thin-right": "The single right angle quote (›) functions as a lightweight breadcrumb separator, a forward-navigation chevron, or an inline bullet alternative in web and print typography. European typographers use it as the closing guillemet in some languages such as Danish, while web designers prefer it over the heavier > symbol for breadcrumbs. At small sizes it is far less visually noisy than a full-sized arrow. HTML entity: &rsaquo;, Unicode: U+203A.",

  "thin-left": "The single left angle quote (‹) is the mirror partner of ›, used as an opening guillemet in Scandinavian and some Central European languages. In breadcrumb trails and carousels it makes an elegant 'previous' chevron that is subtler than a full left-pointing arrow. Its paired use ‹ › gives text a polished, editorial feel borrowed from classic European typography. HTML entity: &lsaquo;, Unicode: U+2039.",

  "arrow-right-bold": "The black right arrow (➡) is a filled, emoji-scale directional arrow that renders in vivid orange-red on iOS, Android, and Windows. It is heavily used in social media posts for bullet-point lists, emphasis, and visually linking one idea to the next. Unlike the line-art → symbol, ➡ carries strong visual weight and pairs naturally with other emoji in captions and messages. Unicode: U+27A1, HTML: &#10145;.",

  "arrow-left-bold": "The black left arrow (⬅) is the filled, emoji-scale counterpart to ➡, pointing firmly leftward in vivid colour on modern devices. Social media creators use ⬅ to direct attention toward an image, link, or previously mentioned item in a thread. Its bold appearance ensures it stands out even in long strings of emoji-rich text. Unicode: U+2B05, HTML: &#11013;.",

  "arrow-up-bold": "The black up arrow (⬆) is an emoji-weight upward arrow rendered with a solid fill on modern operating systems, popular in social posts celebrating growth, rising engagement, or positive news. Finance accounts and sports commentators use ⬆ to signal improvement at a glance. Combined with percentage figures it communicates direction more quickly than words. Unicode: U+2B06, HTML: &#11014;.",

  "arrow-down-bold": "The black down arrow (⬇) delivers a strong visual cue for downloading, scrolling down, or declining values in emoji-rich digital contexts. Its bold fill makes it unmistakeable in lists, comments, and reactions where subtler arrow characters would go unnoticed. Paired with ⬆ it creates an immediately understood up/down pair for comparisons and charts. Unicode: U+2B07, HTML: &#11015;.",

  // ── CURRENCY ────────────────────────────────────────────────────────────────

  "dollar": "The dollar sign ($) is the official currency symbol of the United States dollar and many other dollar-denominated currencies including the Australian, Canadian, and New Zealand dollar. It traces its likely origins to the abbreviation 'ps' for the Spanish peso that evolved visually into a stylised S with a vertical stroke over centuries of handwriting. Beyond currency, $ is used as a variable prefix in programming languages like PHP and Bash, and as a selector prefix in jQuery. Press Shift+4 on any standard keyboard to type it.",

  "euro": "The euro sign (€) was designed in 1997 by Belgian graphic artist Alain Billiet, chosen from a shortlist of thirty-two designs, and officially introduced with the euro currency in 1999. The two horizontal stripes reference the stability of the European currency, while the C shape nods to 'Europe' — intentionally echoing the ancient Greek epsilon (Є). It is one of the most widely used currency symbols globally, covering more than twenty countries and hundreds of millions of daily transactions. Press Option+Shift+2 on Mac or Alt+0128 on Windows.",

  "pound": "The pound sterling sign (£) derives from the capital Latin letter L, an abbreviation of 'libra pondo' — the Roman unit of weight equal to one pound of silver from which English money was historically valued. Today it is the official symbol of the British pound, the fourth most traded currency in the world by forex volume. It also represents currencies in Egypt, Lebanon, Syria, and Sudan, distinguished by context. Press Option+3 on Mac or Alt+0163 on Windows.",

  "yen": "The yen sign (¥) serves double duty as the symbol for both the Japanese yen (JPY) and the Chinese yuan renminbi (CNY), distinguished in practice by accompanying text such as 'JP¥' or 'CN¥'. Japan officially adopted the yen as its currency unit in 1871 and tied it initially to gold and silver standards. Notably, ¥ is also used as the path separator in Japanese Windows systems — where Western keyboards show a backslash (\\), Japanese keyboards display ¥. Press Option+Y on Mac or Alt+0165 on Windows.",

  "rupee": "The Indian rupee sign (₹) was introduced in 2010, designed by D. Udaya Kumar to blend the Devanagari letter Ra (र) with the Latin capital R, with two horizontal stripes echoing the tricolour of the national flag. Before this dedicated Unicode character existed, the rupee was commonly typed using the abbreviated 'Rs' form. The symbol was allocated Unicode U+20B9 and began appearing on keyboards and mobile devices from 2010 onward. India is the world's fifth-largest economy, and ₹ appears in prices across hundreds of millions of transactions daily.",

  "cent": "The cent sign (¢) represents one hundredth of a US dollar and several other dollar-denominated currencies. It appeared on the first US typewriters and was a standard key on mechanical keyboards through most of the twentieth century, though it has been largely dropped from modern keyboards in favour of just typing the numeric value. Retailers still use ¢ in shelf pricing, especially for items priced below a full dollar in American stores. Press Option+4 on Mac or Alt+0162 on Windows.",

  "bitcoin": "The bitcoin sign (₿) was added to Unicode 10.0 in 2017 — almost a decade after the Bitcoin network launched in January 2009 — and represents the world's first and largest cryptocurrency by market capitalisation. The design is a capital B with two vertical strokes, intentionally mirroring the dollar sign but tilted forward to suggest movement. Before Unicode standardisation, bitcoin was often written as BTC or makeshift alternatives like the Thai baht symbol ฿. Unicode: U+20BF, HTML: &#8383;.",

  "ruble": "The ruble sign (₽) is the official currency symbol of the Russian ruble, adopted by the Central Bank of Russia in December 2013 following a public design competition that attracted thousands of entries. The winning design — a capital Р with a horizontal bar — was chosen to be unambiguously identifiable and resist confusion with other Cyrillic letters. Russia's ruble is one of the oldest currencies in continuous use, with origins dating to the thirteenth-century Kievan Rus. Unicode: U+20BD, HTML: &#8381;.",

  "won": "The won sign (₩) is the official currency symbol for the South Korean won (KRW), one of Asia's most actively traded currencies. The horizontal stripes through the W visually distinguish it from a plain letter W in both print and digital typography. South Korea introduced the won as its national currency in 1945 following liberation from Japanese colonial rule. Unicode: U+20A9, HTML: &#8361;.",

  "franc": "The franc sign (₣) represents the historical French franc, the official currency of France until it was replaced by the euro in January 2002 after over six centuries of continuous use. The franc was first struck in gold in 1360 to pay the ransom of King John II of France, held captive by the English after the Battle of Poitiers. Today ₣ is a historical currency symbol, though the Swiss franc (CHF) continues in active circulation without a dedicated Unicode symbol. Unicode: U+20A3, HTML: &#8355;.",

  "lira": "The Turkish lira sign (₺) was introduced in 2012 as Turkey revalued its currency and sought a modern identity for the lira after inflation had severely eroded its value in the early 2000s. The design — an anchor-shaped L with a double crossbar — was selected from thousands of public submissions through a national design competition. Turkey's lira has a history stretching back to the Ottoman Empire, making it one of the older continuously used currency names in the world. Unicode: U+20BA, HTML: &#8378;.",

  "peso": "The Philippine peso sign (₱) distinguishes the Philippine peso (PHP) from the generic P that previously served as its symbol, resolving practical ambiguity with other currencies sharing that letter. The double horizontal bar through the P was standardised in Unicode as U+20B1 and began appearing on Philippine keyboards and official documents. The Philippine peso has roots in Spain's colonial-era currency system and the modern version dates to the establishment of the Bangko Sentral ng Pilipinas in 1949. HTML entity: &#8369;.",

  "dong": "The Vietnamese dong sign (₫) is the currency symbol for the Vietnamese dong (VND), one of the lowest-value currencies by nominal unit — exchange rates are approximately 25,000 dong per one US dollar. The dong has been Vietnam's official currency since 1978 following reunification, and the word đồng means 'coin' or 'bronze' in Vietnamese. The symbol resembles a stylised crossed D referencing the đ character from the Vietnamese alphabet. Unicode: U+20AB, HTML: &#8363;.",

  "hryvnia": "The hryvnia sign (₴) represents the Ukrainian hryvnia (UAH), Ukraine's national currency since 1996 following independence from the Soviet Union. The name 'hryvnia' originates from an ancient monetary and weight unit of Kievan Rus, giving it a history spanning over a thousand years. The symbol is a stylised Cyrillic letter 'г' (ghe) with a double stroke, designed to be instantly recognisable and clearly different from other currency marks. Unicode: U+20B4, HTML: &#8372;.",

  "naira": "The naira sign (₦) is the symbol for the Nigerian naira (NGN), introduced in 1973 when Nigeria decimalised its currency as part of broader post-independence economic reforms. The ₦ design features a capital N with two horizontal bars, styled similarly to the euro and pound signs. Nigeria's economy is the largest in sub-Saharan Africa, making the naira an important currency across the continent. Unicode: U+20A6, HTML: &#8358;.",

  "baht": "The Thai baht sign (฿) represents the Thai baht (THB), one of Southeast Asia's most stable and widely exchanged currencies, popular in regional trade and tourism. Thailand's baht has been in continuous use since the nineteenth century, originally defined as a unit of weight for silver. The ฿ symbol became briefly notorious in early internet discussions when it was used as a makeshift bitcoin symbol before ₿ received its own Unicode code point. Unicode: U+0E3F, HTML: &#3647;.",

  // ── MATH ────────────────────────────────────────────────────────────────────

  "sigma": "The summation sign (∑) is the capital Greek letter sigma used in mathematics to denote the sum of a finite or infinite series — ∑ᵢ aᵢ means 'add all values of a for each index i up to the upper bound'. Introduced by Leonhard Euler in 1755, it has become one of the most fundamental symbols in calculus, statistics, and computer science algorithm analysis. Scientists and engineers encounter it in Fourier series, machine learning loss functions, and statistical sampling. In HTML use &sum; and in LaTeX type \\sum.",

  "pi": "Pi (π) is perhaps the most celebrated mathematical constant, the ratio of a circle's circumference to its diameter, approximately 3.14159265358979 and proven to be both irrational and transcendental. Known and approximated since antiquity by Babylonian, Egyptian, and Chinese mathematicians, it has now been calculated to trillions of decimal places without repeating. Mathematicians and enthusiasts celebrate Pi Day on 14 March (3/14 in US date format). In HTML use &pi; and in most programming languages a PI constant is available in the standard math library.",

  "infinity": "The infinity symbol (∞) was introduced by English mathematician John Wallis in 1655, possibly inspired by the Roman numeral for 1,000 (CIƆ) or the lemniscate curve's form. In mathematics it represents a quantity without bound — ∞ is not a number but a concept used in limits, calculus, and transfinite set theory. In popular culture ∞ symbolises eternal love, continuity, and the limitless, making it one of the most popular motifs in jewellery, tattoos, and logo design. Press Option+5 on Mac or use HTML entity &infin;.",

  "sqrt": "The square root symbol (√) evolved from the lowercase Latin letter 'r' for radix (root), first appearing in print in Christoph Rudolff's 1525 algebra textbook Coss. The horizontal bar extending over the radicand — called the vinculum — was added in later centuries to group the expression unambiguously beneath the radical. Computing languages use sqrt() functions rather than the glyph, but in typeset mathematics the √ radical notation remains the standard. HTML entity: &radic;, Unicode: U+221A.",

  "not-equal": "The not-equal sign (≠) is the standard shorthand for 'is not equal to', used in mathematics, logic, and scientific writing. It combines the equals sign with a diagonal stroke to negate it — a notation that became systematised in twentieth-century mathematical publishing. In programming, languages like Python and JavaScript use != or !== for inequality comparisons, but ≠ is preferred in mathematical typesetting and academic papers. Press Option+= on Mac or use HTML entity &ne;.",

  "less-equal": "The less-than-or-equal-to sign (≤) is a comparison operator combining < with = into a single glyph, indicating that the left value is either smaller than or exactly equal to the right value. It appears constantly in mathematical proofs, programming conditions (written <=), and constraint specifications in optimisation problems. Teachers use ≤ and ≥ in inequality word problems involving budgets, age limits, and measurement tolerances. HTML entity: &le;, Unicode: U+2264.",

  "greater-equal": "The greater-than-or-equal-to sign (≥) indicates that a value meets or exceeds a threshold — 'score ≥ 50 to pass' is a classic classroom example. Alongside ≤, it forms the core vocabulary of inequalities in algebra, calculus, and data analysis. Programming languages represent it as >= in source code. The symbol is ubiquitous in legal specifications, engineering tolerances, and grading criteria. HTML entity: &ge;, Unicode: U+2265.",

  "approximately": "The approximately-equal sign (≈) means 'roughly equal to', used when an exact value is either unknown, impractical to state, or unimportant to the argument at hand. Scientists write π ≈ 3.14, and engineers calculate structural loads as F ≈ 2,500 N to communicate useful precision without false exactness. In everyday writing it appears in casual conversions like '1 mile ≈ 1.6 km'. HTML entity: &asymp;, Unicode: U+2248. Press Option+X on Mac.",

  "integral": "The integral sign (∫) is an elongated S, standing for 'summa' (Latin for sum), introduced by Gottfried Wilhelm Leibniz in 1675 as he and Newton independently developed calculus. The definite integral ∫ₐᵇ f(x) dx computes the net signed area between curve f and the x-axis between limits a and b. Integrals are foundational in physics (work, charge, flux), signal processing, and probability theory. HTML entity: &int;, Unicode: U+222B.",

  "partial": "The partial derivative symbol (∂) distinguishes differentiation with respect to one variable while holding all other variables constant — ∂f/∂x treats y and z as fixed. First used systematically by Adrien-Marie Legendre in the late eighteenth century, it became indispensable in thermodynamics, fluid dynamics, Maxwell's electromagnetic equations, and general relativity. Students affectionately call it 'curly d' to distinguish it from the straight d of ordinary calculus. HTML entity: &part;, Unicode: U+2202.",

  "delta": "The capital Greek letter delta (Δ) is universally used in mathematics and science to denote a finite change or difference — Δx means 'the change in x' as opposed to the infinitesimal dx. In chemistry, Δ above a reaction arrow signals the application of heat. In aviation, a delta-wing aircraft has a triangular planform shape named after this letter. In finance, delta measures an option's price sensitivity to the underlying asset. HTML entity: &Delta;, Unicode: U+0394.",

  "nabla": "The nabla operator (∇) — also called del — represents the gradient, divergence, curl, and Laplacian of a field in vector calculus, making it one of the most powerful single symbols in physics. Its name 'nabla' was chosen by mathematician Peter Guthrie Tait because the inverted triangle (∇) resembled an ancient Assyrian harp of that name. Maxwell's equations of electromagnetism, Einstein's field equations, and the Schrödinger equation of quantum mechanics all rely on ∇. HTML entity: &nabla;, Unicode: U+2207.",

  "times": "The multiplication sign (×) is the standard notation for multiplication in arithmetic and applied sciences, preferred over the dot (·) when clarity is needed. It also represents the Cartesian product of sets (A × B), the cross product of vectors, and appears in screen resolutions (1920×1080) and paper sizes (210×297 mm). In chemistry it appears in stoichiometric ratios. Press Alt+0215 on Windows or use HTML entity &times;.",

  "division": "The division sign (÷) — historically called the obelus — indicates division in arithmetic, as in 12 ÷ 4 = 3. It was popularised in the English-speaking world by Swiss mathematician Johann Rahn in his 1659 algebra book Teutsche Algebra. Though mathematicians increasingly prefer the fraction bar for clarity, ÷ remains ubiquitous in elementary education textbooks and calculator keyboards worldwide. HTML entity: &divide;, Unicode: U+00F7.",

  "plus-minus": "The plus-minus sign (±) expresses both the addition and subtraction possibilities simultaneously, essential for writing scientific measurement uncertainty — '23 ± 0.5 cm' means the true value lies anywhere from 22.5 to 23.5 cm. Engineers use ± in tolerance specifications (shaft diameter 50 ± 0.02 mm) and statisticians include it in confidence intervals and error bars. In mathematics ± represents the two solutions of a quadratic equation, as in the quadratic formula. Press Option+Shift+= on Mac or Alt+0177 on Windows.",

  "degree": "The degree sign (°) marks angular measure (90° is a right angle), temperature in Celsius and Fahrenheit (37°C body temperature), and geographic coordinates (51.5°N for London). It derives from the ancient Babylonian division of a full circle into 360 equal parts, a convention inherited by Greek astronomers and later spread throughout the world. In typography, ° must not be confused with the masculine ordinal indicator (º) or a superscript letter O, which look similar but serve different purposes. Press Option+Shift+8 on Mac or Alt+0176 on Windows.",

  "therefore": "The 'therefore' sign (∴) consists of three dots arranged in an upward-pointing triangle and signals that the preceding statements logically lead to the conclusion that follows — 'all squares are rectangles; this shape is a square, ∴ it is a rectangle'. Introduced in seventeenth-century mathematical writing, it is standard in formal proofs, logic textbooks, and philosophical arguments. Its mirror image ∵ means 'because'. HTML entity: &there4;, Unicode: U+2234.",

  "because": "The 'because' sign (∵) is three dots arranged in a downward-pointing triangle, the logical complement of ∴ ('therefore'). It introduces a reason or justification for the preceding claim — 'the angle is 90° ∵ it is defined as a right angle in the problem'. Less common than ∴ in print, it is nevertheless used in formal proofs and school logic exercises as a compact shorthand. HTML entity: &#8757;, Unicode: U+2235.",

  "empty-set": "The empty set symbol (∅) represents the null set — the unique set that contains absolutely no elements — a foundational concept in set theory and logic. It was introduced by André Weil and the Bourbaki group in 1939, using the Norwegian letter Ø to avoid confusion with the digit zero. The empty set is a subset of every possible set, and its cardinality is zero. In database theory it corresponds to a null result, and in programming it initialises empty collections. HTML entity: &empty;, Unicode: U+2205.",

  "element-of": "The element-of symbol (∈) means 'is a member of' a given set — 'a ∈ A' asserts that the object a belongs to the set A. Introduced by Giuseppe Peano in his 1889 work Arithmetices principia, it is foundational to all of modern mathematics built on set theory. In databases and programming, the concept maps to the SQL IN operator and the Python in keyword for membership tests. HTML entity: &isin;, Unicode: U+2208.",

  "not-element": "The 'not an element of' symbol (∉) negates ∈, asserting that an object does not belong to a set — '5 ∉ {2, 4, 6}' states that 5 is not in the set of even single digits. It is the set-theoretic equivalent of the programming 'not in' operator. In number theory it is used to distinguish types, for instance '√2 ∉ ℚ' (the square root of two is irrational, not in the rationals). HTML entity: &notin;, Unicode: U+2209.",

  "intersection": "The intersection symbol (∩) represents the set of all elements common to two or more sets — A ∩ B contains exactly everything that belongs to both A and B simultaneously. Introduced by Giuseppe Peano, it mirrors the Boolean AND operator and the SQL JOIN operation. In probability theory, P(A ∩ B) is the probability that both events A and B occur together. HTML entity: &cap;, Unicode: U+2229.",

  "union": "The union symbol (∪) represents the set containing all elements from two or more sets combined — A ∪ B includes everything in A, everything in B, and anything shared. It mirrors the Boolean OR operator and the SQL UNION operation in database queries. In probability theory, P(A ∪ B) is the probability that at least one of A or B occurs. HTML entity: &cup;, Unicode: U+222A.",

  "perpendicular": "The perpendicular symbol (⊥) denotes two lines, planes, or vectors meeting at exactly 90 degrees — written AB ⊥ CD to assert the right-angle relationship. In logic it is also used as the symbol for contradiction (falsum or 'bottom'), the claim that can never be true in any interpretation. In linear algebra, ⊥ denotes the orthogonal complement of a subspace. HTML entity: &perp;, Unicode: U+22A5.",

  "proportional": "The proportional-to symbol (∝) expresses that one quantity varies directly with another in a fixed ratio — if y ∝ x, then y = kx for some constant k. Physicists use it extensively: gravitational force F ∝ 1/r², electrical resistance R ∝ L/A, light intensity I ∝ 1/d². It avoids specifying the proportionality constant when its exact value is irrelevant to the conceptual argument. HTML entity: &prop;, Unicode: U+221D.",

  // ── GREEK ───────────────────────────────────────────────────────────────────

  "alpha": "The lowercase Greek letter alpha (α) is the first letter of the Greek alphabet, used across science and mathematics to denote angular acceleration in mechanics, the significance level in hypothesis testing, the alpha-particle in nuclear physics, and a software's earliest pre-release stage. In finance, alpha measures a portfolio's excess return above its benchmark index. The word 'alphabet' itself is derived from alpha and beta, the first two Greek letters. HTML entity: &alpha;, Unicode: U+03B1.",

  "beta": "The lowercase Greek letter beta (β) is the second letter of the Greek alphabet, used to denote beta particles in nuclear physics, the coefficient of thermal expansion in materials science, the beta distribution in statistics, and market risk (systematic beta) in finance. Software in beta testing is feature-complete but undergoing real-world validation — a usage originating from IBM's field-testing terminology in the 1950s. HTML entity: &beta;, Unicode: U+03B2.",

  "gamma": "The lowercase Greek letter gamma (γ) represents gamma radiation — the most energetic form of electromagnetic radiation — as well as the Lorentz factor in special relativity, the shear strain in structural mechanics, and the photon field mediator in quantum electrodynamics. The Gamma function Γ(n) generalises the factorial to non-integer arguments, making it indispensable in complex analysis and combinatorics. In computer graphics, gamma correction adjusts screen brightness to match human visual perception. HTML entity: &gamma;, Unicode: U+03B3.",

  "gamma-upper": "The uppercase Greek letter Gamma (Γ) is best known for the Gamma function Γ(n) = (n−1)! for positive integers, a cornerstone of complex analysis and probability distributions. In thermodynamics Γ sometimes denotes the heat-capacity ratio, and in nuclear physics it labels the energy of gamma-ray emission. The Gamma distribution, parameterised using Γ, models waiting times and failure rates and is widely used in reliability engineering and Bayesian statistics. HTML entity: &Gamma;, Unicode: U+0393.",

  "delta-lower": "The lowercase delta (δ) denotes a small or infinitesimal change (δx), distinguishing it from the macroscopic change Δx in the same quantity. In chemistry, δ+ and δ− label partial charges on atoms in covalently bonded molecules. The Dirac delta function δ(x) is a key tool in signal processing and quantum mechanics for modelling ideal point sources. In topology, the classic epsilon-delta proof uses δ to bound the input neighbourhood corresponding to a given output tolerance ε. HTML entity: &delta;, Unicode: U+03B4.",

  "epsilon": "The lowercase epsilon (ε) is the classic symbol for an arbitrarily small positive number in calculus — the rigorous definition of a limit uses ε and δ to bound output variation and input variation respectively. In machine learning it denotes the learning rate or a small constant added to denominators to prevent division by zero. In graph theory ε sometimes counts the number of edges in a graph. HTML entity: &epsilon;, Unicode: U+03B5.",

  "zeta": "The lowercase zeta (ζ) is the sixth letter of the Greek alphabet, most famous for the Riemann zeta function ζ(s) = Σ n⁻ˢ, whose complex zeros encode the distribution of prime numbers. The still-unproven Riemann Hypothesis asserts that all non-trivial zeros lie on the critical line Re(s) = ½, making it one of the most important open problems in mathematics. In meteorology ζ denotes atmospheric vorticity, and in quantum chemistry it characterises atomic orbital exponents. HTML entity: &zeta;, Unicode: U+03B6.",

  "eta": "The lowercase eta (η) is used in thermodynamics for thermal efficiency (η = W_out / Q_in for a heat engine), in fluid mechanics for dynamic viscosity, and in particle physics for the η meson. The Dedekind eta function η(τ) plays an important role in modular forms and string theory. Statisticians use eta squared (η²) to measure effect size in ANOVA tests as a standardised measure of variance explained. HTML entity: &eta;, Unicode: U+03B7.",

  "theta": "The lowercase theta (θ) is the most common symbol for an angle in geometry and trigonometry — 'find the value of θ' is a stock phrasing in school mathematics problems worldwide. Physicists use θ for polar and spherical coordinate angles, and information theorists use it for unknown model parameters in Bayesian statistics and machine learning. The uppercase Θ (capital theta) denotes tight asymptotic bounds in computer science algorithm complexity analysis. HTML entity: &theta;, Unicode: U+03B8.",

  "iota": "The lowercase iota (ι) is the ninth and smallest letter of the Greek alphabet — the English phrase 'not one iota' means 'not even the tiniest amount', directly referencing iota's reputation as the smallest, least significant Greek letter. In mathematics ι sometimes denotes an inclusion map embedding one set inside another. In linguistics it labels a high front vowel. HTML entity: &iota;, Unicode: U+03B9.",

  "kappa": "The lowercase kappa (κ) is used in differential geometry for the curvature of a curve (κ = 1/r for a circle of radius r), in optics for the imaginary part of the complex refractive index controlling absorption, and in thermodynamics for thermal conductivity. Cohen's kappa statistic (κ) is the standard measure of inter-rater agreement in statistics and machine learning evaluation. HTML entity: &kappa;, Unicode: U+03BA.",

  "lambda": "The lowercase lambda (λ) represents wavelength in physics (λ = c/f for electromagnetic waves), the rate parameter of the Poisson and exponential distributions in statistics, and anonymous functions in computer science — Python, Java, and Haskell all borrow the term 'lambda' from Alonzo Church's lambda calculus of the 1930s. AWS Lambda, the widely used serverless computing platform, is also named after this concept. HTML entity: &lambda;, Unicode: U+03BB.",

  "mu": "The lowercase mu (μ) wears many scientific hats: the SI prefix for micro- (10⁻⁶) in units like μm and μg, the population mean in statistics, the coefficient of friction in mechanics, the magnetic permeability of a material, and the mean of a Poisson process. In pharmacology, μg denotes micrograms — a critical distinction in drug dosing. The μ-operator in computability theory defines the smallest value satisfying a given predicate. HTML entity: &mu;, Unicode: U+03BC.",

  "nu": "The lowercase nu (ν) represents frequency in physics (ν = c/λ for light) and kinematic viscosity in fluid mechanics (distinct from dynamic viscosity η). In quantum mechanics ν labels the vibrational quantum number of a diatomic molecule. Its visual similarity to the Latin letter v means ν must be used carefully in handwritten equations to avoid ambiguity. HTML entity: &nu;, Unicode: U+03BD.",

  "xi": "The lowercase xi (ξ) is used in mathematics to denote generalised coordinates in Lagrangian and Hamiltonian mechanics, random variables in certain probability notations, and the Riemann xi function in number theory. In topology ξ labels characteristic classes of vector bundles. Its complex, multi-stroke shape makes it one of the more challenging Greek letters to handwrite clearly, earning it the nickname 'squiggly' among students. HTML entity: &xi;, Unicode: U+03BE.",

  "omicron": "The lowercase omicron (ο) looks identical to the Latin letter o and is therefore almost never used as a mathematical symbol to avoid ambiguity. It is the fifteenth letter of the Greek alphabet and its name means 'small o' in Greek. The letter gained widespread public recognition when the WHO named the Omicron variant of SARS-CoV-2 in November 2021, choosing it in alphabetical order from the Greek alphabet. HTML entity: &#959;, Unicode: U+03BF.",

  "rho": "The lowercase rho (ρ) represents electrical resistivity in material science, mass density in physics (ρ = m/V), and the Spearman rank-correlation coefficient in statistics. In finance ρ measures an option's price sensitivity to changes in the risk-free interest rate. The uppercase Ρ is visually identical to the Latin P, so lowercase ρ is far more common in scientific notation. HTML entity: &rho;, Unicode: U+03C1.",

  "sigma-lower": "The lowercase sigma (σ) is the universal symbol for standard deviation — the measure of data spread around the mean — making it one of the most frequently encountered Greek letters in statistics, data science, and quality control. In materials science σ denotes tensile stress; in electrical engineering it represents electrical conductivity; and in particle physics it labels scattering cross-sections. The Six Sigma manufacturing and business quality methodology derives its name from six standard deviations. HTML entity: &sigma;, Unicode: U+03C3.",

  "tau": "The lowercase tau (τ) represents the time constant in RC electrical circuits (τ = RC, the time to charge to 63.2% of full voltage), torque in mechanics, shear stress in materials science, and optical depth in astrophysics. A growing movement advocates τ = 2π ≈ 6.283 as a more natural circle constant, arguing it simplifies a wide range of formulas compared to π. In the Standard Model of particle physics the tau lepton (τ) is the heaviest of the three charged leptons. HTML entity: &tau;, Unicode: U+03C4.",

  "phi": "The lowercase phi (φ) encodes the golden ratio φ = (1 + √5)/2 ≈ 1.618, a proportion observed in the Parthenon, nautilus shell spirals, the arrangement of sunflower seeds, and many works of art and architecture. In physics φ represents electric potential and the azimuthal angle in spherical coordinates. In formal logic and set theory φ is a common placeholder variable for an arbitrary formula. HTML entity: &phi;, Unicode: U+03C6.",

  "chi": "The lowercase chi (χ) is central to the chi-squared distribution (χ²), the most widely used statistical test for goodness-of-fit and independence in contingency tables. In physics χ denotes electric susceptibility; in topology it labels the Euler characteristic of a surface. The Chi-Rho monogram (☧), combining χ and ρ, is one of the earliest and most enduring Christian symbols. HTML entity: &chi;, Unicode: U+03C7.",

  "psi": "The lowercase psi (ψ) is best known as the quantum wave function in Schrödinger's equation — |ψ|² gives the probability density of finding a particle at a given position in space. In psychology ψ is used as a shorthand for the entire discipline, and in parapsychology it labels purported psychic or extrasensory phenomena. In fluid mechanics ψ denotes the stream function used to describe inviscid flow. HTML entity: &psi;, Unicode: U+03C8.",

  "omega": "The lowercase omega (ω) represents angular velocity (ω = 2πf, measured in radians per second) in rotational mechanics and the angular frequency of any oscillating signal. In set theory ω labels the first infinite ordinal, the set of all natural numbers. The lowercase ω appears constantly in signal processing, electrical engineering, and wave equations, while the uppercase Ω (below) carries different specialised meanings. HTML entity: &omega;, Unicode: U+03C9.",

  "omega-upper": "The uppercase omega (Ω) is the twenty-fourth and final letter of the Greek alphabet — giving rise to the expression 'from alpha to omega' meaning 'from beginning to end'. In electrical engineering Ω is the SI unit of electrical resistance (ohms), named in honour of German physicist Georg Simon Ohm. In algorithm analysis Ω-notation describes asymptotic lower bounds: an algorithm is Ω(n log n) if it cannot be faster than n log n in the worst case. HTML entity: &Omega;, Unicode: U+03A9.",

  // ── LEGAL & TRADE ───────────────────────────────────────────────────────────

  "copyright": "The copyright symbol (©) indicates that the creator of a work — text, music, artwork, software, film — reserves all reproduction rights under copyright law, without requiring registration in most countries since the Berne Convention of 1886. Placing © with the year and the rights-holder's name is recommended practice even though it is no longer a legal requirement in most jurisdictions following that convention. The symbol was first codified as a legal marker in the US Copyright Act of 1909. Press Option+G on Mac or Alt+0169 on Windows.",

  "registered": "The registered trademark symbol (®) denotes that a trademark or service mark has been officially registered with a national intellectual property office such as the USPTO, USPTO, or UKIPO, conferring the legal right to exclusive use and protection against infringement. Unregistered marks use the ™ symbol instead while the registration is pending or simply asserted under common law. Registration requirements, costs, renewal periods, and remedies vary by country. Press Option+R on Mac or Alt+0174 on Windows.",

  "trademark": "The trademark symbol (™) is placed after a brand name, logo, or slogan to assert trademark rights even without formal registration — a common practice in countries like the United States that recognise common-law trademark through first use in commerce. It signals intent to claim and protect the mark and can deter potential infringers. Once the trademark is officially registered, brands switch from ™ to ®. Press Option+2 on Mac or Alt+0153 on Windows.",

  "service-mark": "The service mark (℠) functions like the trademark symbol (™) but applies specifically to services — airlines, banks, insurance firms, and restaurants — rather than physical goods. Its use is primarily an American practice, though the concept of service marks is recognised internationally under the Madrid System. In most international contexts ™ is more widely understood and can substitute without confusion. Unicode: U+2120, HTML: &#8480;.",

  "sound-recording": "The sound recording copyright symbol (℗) — the circled P, from 'phonogram' — protects the rights of record labels and recording producers in the specific audio recording itself, distinct from the © that covers the underlying musical composition and lyrics. The Rome Convention of 1961 introduced this distinction into international intellectual property law. You will find ℗ in album liner notes, streaming platform metadata, and broadcast licensing agreements. Unicode: U+2117, HTML: &#8471;.",

  "section": "The section sign (§) is used in legal documents, statutes, regulations, and academic citations to reference a numbered section — '§ 42 of the Civil Rights Act states…'. Its name derives from the Latin word sectio (a cutting). In Germany it appears as a dedicated key on keyboard layouts and is so frequently used in German legal writing that lawyers informally call it the 'Paragraph-Zeichen'. Press Option+6 on Mac or Alt+0167 on Windows.",

  "paragraph": "The pilcrow (¶), also called the paragraph mark or blind P, has been used since medieval manuscripts to signal a new thought or passage, originally drawn in red ink by a rubricator before the main scribe left a space. In modern word processors, toggling the ¶ display reveals hidden formatting symbols — paragraph breaks, spaces, and tabs — essential for diagnosing layout and typography problems. It also appears in legal, academic, and legislative citations to reference specific paragraphs within a document. Press Option+7 on Mac or Alt+0182 on Windows.",

  "dagger": "The dagger (†) serves as the second footnote reference mark in traditional typesetting hierarchy, following the asterisk (*) — typically appearing at the bottom of a dictionary definition or academic paper to indicate a second footnote. It also conventionally marks a deceased person's name in genealogy, biography, and historical texts — for example, 'W. A. Mozart †1791' — where it symbolises death. The double dagger ‡ is used for the third footnote when three or more are needed on a single page. Press Alt+0134 on Windows or use HTML entity &dagger;.",

  "double-dagger": "The double dagger (‡), also called a diesis or double obelisk, is the third footnote reference mark in the classic typesetting sequence: * asterisk, † dagger, ‡ double dagger. Academic publishers, legal texts, and dictionaries use it when a single page has three or more footnotes that require distinct markers. In some linguistic dictionaries ‡ additionally flags an archaic, obsolete, or reconstructed word form. Press Alt+0135 on Windows or use HTML entity &Dagger;.",

  // ── SHAPES & STARS ──────────────────────────────────────────────────────────

  "star-filled": "The solid black star (★) is used for ratings, military rank insignia, national flags, and decorative lists across virtually every culture in the world. Its bold, filled form catches the eye more effectively than the outline ☆, making it the default choice for star-rating widgets on e-commerce sites and app stores. Five-pointed stars have appeared on flags, coats of arms, and religious symbols across ancient and modern civilisations for millennia. Unicode: U+2605, HTML: &#9733;.",

  "star-outline": "The white (outline) star (☆) represents an unfilled or unchosen rating, typically displayed alongside ★ in five-star rating systems to show the user's score against the maximum. It also serves as a decorative flourish in headlines, social media bios, and list markers. In astronomy and celestial navigation, hollow-star markers on charts distinguish star magnitude classes. Unicode: U+2606, HTML: &#9734;.",

  "star": "The filled star (★) is the definitive symbol for ratings, reviews, and bookmarks across the digital world — iOS, Android, Google, Amazon, and Yelp all use the five-star scale. Its compact, distinctive shape communicates quality at a glance without requiring any text label. Stars also appear as favourites icons, achievement badges, and 'save for later' buttons in a wide variety of apps. Unicode: U+2605, HTML: &#9733;.",

  "heart-filled": "The black heart suit (♥) is one of the four suits in a standard playing-card deck and a widely recognised symbol of love in everyday digital communication. Unlike the red emoji heart ❤️, the ♥ character is the monochrome typographic heart used in card-game notation, musical scores, and plain-text contexts. Chess and card-game applications rely on this Unicode character to display hands and deal history. Unicode: U+2665, HTML: &#9829;.",

  "heart-outline": "The white (hollow) heart suit (♡) is the unfilled counterpart to ♥, used in card games for empty suit slots and in ratings interfaces to represent an unchosen 'like' state. In Japanese and Korean pop culture and fandom communities ♡ is ubiquitous in decorative text, social media bios, and fan-art captions. Unicode: U+2661, HTML: &#9825;.",

  "heart": "The classic heart (❤) is the single most recognised symbol of love, affection, and 'like' in digital communication, predating emoji by many decades as a typographic character. Twitter popularised a heart-shaped like button in 2015 when it replaced its star icon, a change that spread the heart's meaning as 'approval' far beyond romantic contexts. The plain ❤ renders reliably in HTML and email clients as a vivid red heart without requiring emoji variation selectors. Unicode: U+2764, HTML: &#10084;.",

  "diamond-filled": "The black diamond suit (♦) is one of the four playing-card suits and a geometric shape used as a bullet point, directional indicator, and stylistic flourish in typography. Its compact rhombus form makes it a popular alternative to the round bullet (•) for a more angular, distinctive list style. In ANSI flowcharts a diamond shape traditionally marks a decision node. Unicode: U+2666, HTML: &#9830;.",

  "diamond-outline": "The white (outline) diamond (◇) is used as a gentle bullet point, decorative separator, and playing-card suit outline in printing and digital typography. In musical notation for fretted instruments it represents a harmonic — a note produced by lightly touching the string. Inline, ◇ creates a balanced separator that is less assertive than a bullet point or arrow. Unicode: U+25C7, HTML: &#9671;.",

  "club-filled": "The black club suit (♣) is one of the four playing-card suits, its three-leaf design derived from the trefoil or clover. It is known as 'trefle' in French and 'Kreuz' (cross) in German card traditions, reflecting different cultural interpretations of the same shape. In social media posts and casual writing ♣ serves as a leafy decorative element. Unicode: U+2663, HTML: &#9827;.",

  "spade-filled": "The black spade suit (♠) — the highest-value suit in bridge and many other card games — is shaped like a sword tip or stylised shovel head, reflecting the Spanish word espada (sword) from which the suit name originates. In typographic design it provides a distinctive geometric bullet with a pointed top and rounded base. Unicode: U+2660, HTML: &#9824;.",

  "circle-filled": "The solid black circle (●) is one of the most versatile typographic characters: a filled-dot bullet point, a state indicator in dashboards, and a perfect pixel-consistent circle in diagrams and charts. It represents the selected state of radio buttons in print forms and UI mockups. At different sizes it serves as a custom period, a music note glyph, or a minimal map pin. Unicode: U+25CF, HTML: &#9679;.",

  "circle-outline": "The white (hollow) circle (○) represents emptiness, potential, and open choices — it is the unselected state of radio buttons in paper forms and UI patterns. In Japan ○ signals correctness or 'OK' (the opposite of × which means incorrect), a cultural difference travellers sometimes find surprising. In chess notation ○ occasionally marks a good move alternative. Unicode: U+25CB, HTML: &#9675;.",

  "square-filled": "The solid black square (■) is a strong, rectangular bullet point used in business presentations, infographics, progress indicators, and pixel-art. In mathematical typography, ■ at the end of a proof is called the Halmos symbol or 'tombstone', signalling QED ('which was to be demonstrated'). In character-cell terminals it fills entire character cells. Unicode: U+25A0, HTML: &#9632;.",

  "square-outline": "The white (outline) square (□) is the standard unchecked checkbox on paper forms, PDF documents, and physical sign-up sheets where digital interactivity is not available. In modal logic □ is the 'necessity' operator — □P means 'it is necessarily true that P'. Unicode: U+25A1, HTML: &#9633;.",

  "triangle-up": "The solid upward-pointing triangle (▲) signals increase, ascending sort order, and upward navigation on dashboards, sortable tables, and financial charts. Volume controls on physical hardware devices often use ▲ to indicate louder. In hazard pictograms worldwide, a yellow upward triangle frames warning symbols such as electricity and biohazard markers. Unicode: U+25B2, HTML: &#9650;.",

  "triangle-down": "The solid downward-pointing triangle (▼) signals decrease, descending sort order, and dropdown menus in interface design. Financial tables use ▼ next to falling prices or declining percentages. Volume controls use ▼ for quieter. In chemistry, a downward triangle within a hexagonal outline is one convention for drawing a benzene ring. Unicode: U+25BC, HTML: &#9660;.",

  "snowflake": "The snowflake (❄) represents winter, cold temperatures, and frozen conditions in weather icons, seasonal marketing, and decorative use on greeting cards and holiday content. The hexagonal symmetry of natural snowflakes arises from the molecular structure of ice, and no two are believed to be exactly identical — a fact that makes the snowflake a symbol of uniqueness as well as beauty. In data engineering, Snowflake is a leading cloud data warehouse platform named after this symbol. Unicode: U+2744, HTML: &#10052;.",

  "flower": "The black florette (✿) is a decorative four-petalled flower symbol from the classic dingbat tradition used in titles, section dividers, and ornamental typography. It originates from the printer's floral ornament collections of the nineteenth century and appears in many professional typefaces as a decorative accessory character. Paired with ❀ and ✾ it creates elegant floral borders and dividers. Unicode: U+273F, HTML: &#10047;.",

  "cross": "The Latin cross (✝) is the primary symbol of Christianity, representing the crucifixion of Jesus of Nazareth and embraced by billions of Christians worldwide. It appears in church architecture, ecclesiastical art, memorials, and national flags. The Latin cross has a longer lower arm than the Greek cross (+), which has equal arms. Unicode: U+271D, HTML: &#10013;.",

  "checkmark": "The check mark (✓) is the universal symbol for 'yes', 'correct', 'done', and 'selected' across forms, tests, checklists, and digital interfaces. Its use is especially prevalent in English-speaking countries; in some European countries a similar mark can indicate incorrectness, so cultural context matters for international documents. HTML checkboxes render a ✓ or ✔ when checked. Unicode: U+2713, HTML: &#10003;.",

  "heavy-check": "The heavy check mark (✔) is a bolder, thicker version of ✓ designed to be visually prominent at small sizes and in low-resolution or low-contrast print. Email marketing campaigns, landing pages, and feature comparison tables widely use a green ✔ to signal included or available benefits. Its weight ensures visibility even in dense information layouts. Unicode: U+2714, HTML: &#10004;.",

  "x-mark": "The ballot X (✗) signals 'no', 'incorrect', 'not included', or 'delete' — the visual opposite of ✓. It appears in multiple-choice test answer sheets, checklist printouts, and UI error indicators. In some European countries students traditionally mark correct answers with ✗ rather than ✓, so context is important for international documents. Unicode: U+2717, HTML: &#10007;.",

  "heavy-x": "The heavy ballot X (✘) is the bold, visually dominant version of ✗, used where the rejection or error must be unmissable — printed in red on forms, applied to 'feature unavailable' indicators in comparison tables, and used in critical warning labels. Its strong, filled strokes ensure legibility at all print sizes and screen resolutions. Unicode: U+2718, HTML: &#10008;.",

  // ── PUNCTUATION ─────────────────────────────────────────────────────────────

  "left-double-quote": "The left (opening) double quotation mark (U+201C, HTML &ldquo;) is the typographically correct opening quotation mark used in American, British, Australian, and many other English-language typesetting traditions, distinct from the straight ASCII neutral quote (U+0022). Design guidelines from Apple, Microsoft, Oxford University Press, and the Chicago Manual of Style all specify curved smart quotes over the plain keyboard alternative. Correct use of opening and closing curly quotes signals typographic care and professionalism. Press Option+[ on Mac or insert the HTML entity &ldquo;.",

  "right-double-quote": "The right (closing) double quotation mark (U+201D, HTML &rdquo;) closes a quotation and also serves as the typographically correct inch symbol, e.g. 6 inches tall. Balanced open-and-close curly quote pairs are required by all major editorial style guides. Many modern text editors auto-substitute the straight ASCII quote character with the correct curly pair as you type. Press Option+Shift+[ on Mac or use HTML entity &rdquo;.",

  "left-single-quote": "The left (opening) single quotation mark (U+2018, HTML &lsquo;) opens single-quoted text inside a double-quoted passage and serves as the typographic apostrophe at the start of contractions. It distinctly curls toward the text it opens, unlike the straight neutral apostrophe. HTML entity: &lsquo;, Mac: Option+].",

  "right-single-quote": "The right (closing) single quotation mark and apostrophe (U+2019, HTML &rsquo;) serves dual duty: it closes single-quoted passages and forms the apostrophe in contractions such as dont, its, and possessives. Using the correct curly form instead of the straight ASCII tick produces noticeably more polished typesetting across all print and screen media. HTML entity: &rsquo;, Mac: Option+Shift+].",

  "double-angle-left": "The left double angle quotation mark (U+00AB, HTML &laquo;) called a guillemet is the standard opening quotation character in French, Italian, Spanish, Russian, Greek, and many other languages. In French typography a thin non-breaking space is traditionally inserted between the guillemet and the first word of the quoted text. HTML entity: &laquo;, Unicode: U+00AB.",

  "double-angle-right": "The right double angle quotation mark (U+00BB, HTML &raquo;), the closing guillemet, mirrors its opening partner and closes quotations in French, Italian, Spanish, and other European typographic traditions. In shell commands and programming documentation it sometimes indicates output redirection. HTML entity: &raquo;, Unicode: U+00BB.",

  "em-dash": "The em dash (—) is the longest and most versatile dash in English punctuation, used to set off parenthetical remarks — like this one — with stronger visual emphasis than commas or parentheses. Named because its width equals that of the capital letter M, it also replaces a missing or redacted word and introduces a summary after a list. US style places no spaces around em dashes; British and Australian styles sometimes add a space. Mac: Option+Shift+−, Windows: Alt+0151.",

  "en-dash": "The en dash (–) is half an em in width and has two primary uses: indicating numerical ranges (pages 12–24, 2020–2023) and linking compound modifiers where one element is multi-word (a post–World War II economy, a London–New York flight). It is subtly but importantly distinct from both the hyphen (-) and the em dash (—). Most style guides recommend no spaces for ranges but a space on each side for compound modifiers. Mac: Option+−, Windows: Alt+0150.",

  "ellipsis": "The ellipsis (…) represents omitted text in a quotation, trailing-off speech, or a meaningful pause — three distinct functions that some style guides distinguish with spacing rules. Unicode provides it as a single character (…) rather than three separate periods, ensuring consistent spacing across all typefaces and rendering engines. In menus and UI, an ellipsis after a menu item signals that a further dialog or sheet will appear before the action completes. Mac: Option+;, HTML: &hellip;.",

  "bullet": "The bullet point (•) is the default list marker for unordered lists in presentations, marketing copy, and instructional writing where sequence is irrelevant. Its round, symmetrical form draws the eye to each list item without adding the hierarchical weight of a number or letter. The bullet character (U+2022) renders consistently across all platforms, fonts, and email clients. Mac: Option+8, Windows: Alt+0149.",

  "middle-dot": "The interpunct or middle dot (·) sits at the vertical midpoint of a line and serves multiple purposes: a multiplication symbol in some European countries (3·4 = 12), a syllable separator in Catalan orthography (col·legi), a decimal separator in some older British notation, and a list separator in ancient Greek inscriptions. Wikipedia uses the middle dot to separate items in navigation path breadcrumbs. HTML entity: &middot;, Unicode: U+00B7.",

  "soft-hyphen": "The non-breaking hyphen (‑, U+2011) looks identical to a regular hyphen in normal rendering but instructs the line-breaking algorithm never to break the line at its position. It is used in hyphenated compound words, phone numbers (1‑800‑555‑0100), and part codes that must remain on a single line regardless of the container width. Contrast with the soft hyphen (U+00AD) which allows a break if needed. HTML entity: &#8209;.",

  "interrobang": "The interrobang (‽) elegantly combines the question mark and exclamation point into a single glyph for sentences that are simultaneously exclamatory and questioning — 'You ate the whole pizza‽' It was invented in 1962 by advertising executive Martin Speckter, who considered two adjacent marks (?!) typographically clumsy. Despite its intuitive appeal and dedicated Unicode code point, the interrobang has not been widely adopted in mainstream publishing or journalism style guides. Unicode: U+203D.",

  // ── MUSIC ───────────────────────────────────────────────────────────────────

  "music-note": "The quarter note (♩), also called a crotchet, is the basic rhythmic unit in common (4/4) time signature, lasting one beat per measure. Its stem and solid oval head are the most fundamental elements of Western music notation. In informal digital use, ♩ and the eighth note ♪ appear in song titles, playlist icons, and social media bios as a simple 'music' visual without literal rhythmic meaning. Unicode: U+2669, HTML: &#9833;.",

  "eighth-note": "The eighth note (♪), also called a quaver, lasts half a beat in common time and is the most recognised music symbol in everyday consumer use — appearing on music-streaming apps, merchandise, and decorative text everywhere. Its single flagged stem is immediately understood as 'music' by people with no formal musical training. Copy it for music-themed social media posts, channel names, or decorative headings. Unicode: U+266A, HTML: &#9834;.",

  "beamed-notes": "Two beamed eighth notes (♫) represent a pair of quavers joined by a horizontal beam across their stems, used in music notation to group notes within a beat. In everyday digital use ♫ is the go-to 'music is playing' icon — appearing in messaging apps, music players, and notification banners. Many text autocomplete systems suggest ♫ when the user types music-related keywords. Unicode: U+266B, HTML: &#9835;.",

  "beamed-two": "The double-beamed sixteenth notes (♬) show two semiquavers joined by two parallel beams, each note lasting a quarter of a beat in common time. Like ♫, it serves as a decorative music icon in contexts requiring a single recognisable 'musical notes' character. Its double beam gives it a slightly more energetic visual feel than ♫ for high-tempo music content. Unicode: U+266C, HTML: &#9836;.",

  "treble-clef": "The treble clef (𝄞) — properly the G clef — is the most common clef in sheet music, placed at the beginning of the staff on the second line to identify that line as the note G4 (the G above middle C). It is the symbol that non-musicians most associate with the concept of 'music'. The Unicode character 𝄞 lives in the Supplementary Multilingual Plane at U+1D11E and requires a surrogate pair in older UTF-16 systems. HTML: &#119070;.",

  "flat": "The music flat sign (♭) lowers a note by one semitone when placed immediately before it in sheet music. It is one of three standard accidentals alongside the sharp (♯) and natural (♮). In everyday writing ♭ appears in chord names (B♭ major, E♭ minor) and in the names of musical keys. The ♭ character is distinct from the letter b, though their visual similarity occasionally causes confusion in plain text. HTML: &#9837;.",

  "natural": "The music natural sign (♮) cancels a previous sharp or flat, restoring the note to its unaltered diatonic pitch within the key signature. It appears in sheet music whenever a note that was sharpened or flattened earlier in the measure must return to its natural state. There is no keyboard shortcut on standard layouts — ♮ must be inserted via Unicode or a music-notation application. HTML: &#9838;.",

  "sharp": "The music sharp sign (♯) raises a note by one semitone and should not be confused with the number/hash sign (#) — ♯ has two slanted staff lines while # has two horizontal lines, making them clearly different in careful typography. It appears in key signatures, chord names (C♯ minor, F♯ major), and instrument-tuning notation. The programming language 'C#' uses the standard hash character rather than the true musical ♯, despite the name's intention. HTML: &#9839;.",

  // ── CHESS & GAMES ───────────────────────────────────────────────────────────

  "white-king": "The white chess king (♔) is the most important piece on the board — its capture (checkmate) ends the game — though it is one of the least mobile, permitted to move only one square in any direction per turn. Tournament players use K in algebraic notation for the king. In Unicode, chess pieces are available as plain-text characters for move annotations, puzzle publications, and decorative use in documents. Unicode: U+2654.",

  "white-queen": "The white chess queen (♕) is the most powerful piece on the board, capable of moving any number of squares horizontally, vertically, or diagonally. Algebraic notation uses Q for the queen. The queen in its modern omnidirectional form replaced the slower-moving 'fers' piece in fifteenth-century European chess, dramatically accelerating the pace of the game. Unicode: U+2655.",

  "white-rook": "The white chess rook (♖), also called the castle due to its tower-like appearance, moves any number of squares horizontally or vertically and participates in the special castling move that tucks the king behind the rook for safety. The rook is the second-most valuable piece after the queen in standard piece-value tables. Unicode: U+2656.",

  "white-bishop": "The white chess bishop (♗) moves any number of squares diagonally and remains on the same colour of square for the entire game — one bishop serves light squares, the other dark. A pair of bishops working together is generally considered a strategic advantage on open boards. The bishop's diagonal mobility makes it especially powerful when the centre is open. Unicode: U+2657.",

  "white-knight": "The white chess knight (♘) is uniquely able to jump over other pieces, moving in an L-shape: two squares in one direction then one square perpendicular. Knights are valued for their ability to fork multiple pieces simultaneously and for their usefulness in closed positions where bishops and rooks are blocked. The Unicode knight symbols are widely used in puzzle diagrams and annotated game scores. Unicode: U+2658.",

  "white-pawn": "The white chess pawn (♙) is the most numerous piece, advancing one square at a time (or two from its starting rank) and capturing diagonally. A pawn that reaches the opposite end of the board promotes to any other piece — almost always a queen. Endgame theory and strategic planning in chess revolve heavily around pawn structure, passed pawns, and promotion races. Unicode: U+2659.",

  "black-king": "The black chess king (♚) mirrors the white king (♔) in all rules and importance, filled to visually represent the dark-coloured side. In chess problems and game diagrams it is essential for clearly distinguishing white and black pieces at a glance. Algebraic notation uses K for both kings, distinguished by context. Unicode: U+265A.",

  "black-queen": "The black chess queen (♛) is the filled mirror of the white queen (♕), equal in power and value but representing the dark pieces. In computer-generated game transcripts and diagrams the filled symbol distinguishes black's pieces clearly from white's. Unicode: U+265B.",

  "black-rook": "The black chess rook (♜) is the dark-side counterpart of ♖, essential in back-rank checkmate patterns where a rook delivers mate along the first rank. In algebraic notation rook moves look the same for both colours — context determines whose rook moved. Unicode: U+265C.",

  "black-bishop": "The black chess bishop (♝) complements the white bishop in game diagrams and notation, moving identically but representing the dark pieces. Each side possesses two bishops covering opposite-coloured squares; together they provide comprehensive diagonal coverage of the entire board. Unicode: U+265D.",

  "black-knight": "The black chess knight (♞) has the same distinctive L-shaped jumping move as its white counterpart, making it one of the trickiest pieces to counter because it can reach squares no other piece can threaten from that position. The Unicode symbol is used in annotated game scores, puzzle books, and instructional diagrams. Unicode: U+265E.",

  "black-pawn": "The black chess pawn (♟) is the dark counterpart of the white pawn (♙), moving downward on a conventional board diagram and capturing diagonally forward in its direction of travel. The Unicode black pawn alone (♟) has gained an independent cultural life as a popular decorative symbol in social media and creative design. Unicode: U+265F.",

  "die-1": "The die face showing one pip (⚀) is the first of six Unicode characters that encode the faces of a standard six-sided die. These characters are used in tabletop role-playing game documentation, probability textbooks, and game design materials where inserting a photograph or vector graphic is impractical. The complete set ⚀⚁⚂⚃⚄⚅ forms a full die face sequence in plain text. Unicode: U+2680.",

  "die-6": "The die face showing six pips (⚅) is the highest value on a standard six-sided die. In tabletop gaming culture, rolling a six is traditionally a critical hit or maximum result, making ⚅ a symbol of luck and success. It is the most visually dense of the six Unicode die characters, with pips filling all three rows on both columns. Unicode: U+2685.",

  // ── ZODIAC ──────────────────────────────────────────────────────────────────

  "aries": "The Aries zodiac symbol (♈) represents the Ram and covers birthdays from 21 March to 19 April — the first sign of the Western zodiac and the one that opens the astrological year at the vernal equinox. In astrology, Aries is a cardinal fire sign ruled by Mars, associated with initiative, courage, and bold energy. The glyph resembles the curved horns of a ram. Unicode: U+2648.",

  "taurus": "The Taurus zodiac symbol (♉) represents the Bull and spans 20 April to 20 May, the second sign of the Western zodiac. It is a fixed earth sign ruled by Venus, associated with stability, sensory pleasure, determination, and an appreciation for beauty and luxury. The glyph depicts a circle with two curved horns, evoking the bull's head. Unicode: U+2649.",

  "gemini": "The Gemini zodiac symbol (♊) represents the Twins and covers 21 May to 20 June, the third sign of the zodiac. It is a mutable air sign ruled by Mercury, associated with communication, intellectual curiosity, duality, and adaptability. The glyph resembles the Roman numeral II, directly referencing the twin theme. Unicode: U+264A.",

  "cancer": "The Cancer zodiac symbol (♋) represents the Crab and spans 21 June to 22 July, the fourth sign of the zodiac and the one associated with the summer solstice. It is a cardinal water sign ruled by the Moon, associated with emotional depth, family ties, home, and nurturing instincts. The glyph is often interpreted as two intertwined spirals or the claws of a crab. Unicode: U+264B.",

  "leo": "The Leo zodiac symbol (♌) represents the Lion and covers 23 July to 22 August, the fifth sign of the zodiac. It is a fixed fire sign ruled by the Sun, associated with royalty, creativity, dramatic expression, and natural leadership. The glyph is thought to resemble a stylised lion's mane curling into a tail. Unicode: U+264C.",

  "virgo": "The Virgo zodiac symbol (♍) represents the Maiden or Grain Goddess and spans 23 August to 22 September, the sixth sign of the zodiac. It is a mutable earth sign ruled by Mercury, associated with analytical thinking, precision, health, and service to others. The glyph resembles the letter M with a distinctive looped or curved tail. Unicode: U+264D.",

  "libra": "The Libra zodiac symbol (♎) represents the Scales and covers 23 September to 22 October, the seventh sign of the zodiac. It is a cardinal air sign ruled by Venus, associated with justice, balance, harmony, and partnership. Libra is unique among zodiac signs in being represented by an inanimate object rather than a living creature or person. Unicode: U+264E.",

  "scorpio": "The Scorpio zodiac symbol (♏) represents the Scorpion and spans 23 October to 21 November, the eighth sign of the zodiac. It is a fixed water sign co-ruled by Mars and Pluto, associated with intensity, transformation, mystery, and psychological depth. The glyph resembles an M with a pointed, upward-curving tail symbolising the scorpion's sting. Unicode: U+264F.",

  "sagittarius": "The Sagittarius zodiac symbol (♐) represents the Archer — a centaur aiming a bow — and covers 22 November to 21 December, the ninth sign of the zodiac. It is a mutable fire sign ruled by Jupiter, associated with philosophy, adventure, optimism, and the pursuit of higher knowledge. The glyph depicts an arrow pointing diagonally upward and to the right. Unicode: U+2650.",

  "capricorn": "The Capricorn zodiac symbol (♑) represents the Sea-Goat — a mythological creature with a goat's body and a fish's tail — and spans 22 December to 19 January, the tenth sign of the zodiac. It is a cardinal earth sign ruled by Saturn, associated with ambition, discipline, responsibility, and long-term planning. The glyph blends the letters V and S with a curling fish-tail. Unicode: U+2651.",

  "aquarius": "The Aquarius zodiac symbol (♒) represents the Water Bearer and covers 20 January to 18 February, the eleventh sign of the zodiac. Despite its watery symbolism, Aquarius is an air sign ruled by Saturn and Uranus, associated with innovation, humanitarian ideals, independence, and progressive thinking. The glyph shows two wavy parallel lines representing flowing water or electrical waves. Unicode: U+2652.",

  "pisces": "The Pisces zodiac symbol (♓) represents the Fish and spans 19 February to 20 March, the twelfth and final sign of the zodiac. It is a mutable water sign ruled by Jupiter and Neptune, associated with intuition, compassion, artistic sensitivity, and a tendency to dream. The glyph depicts two fish swimming in opposite directions, connected by a cord — symbolising the Piscean pull between contrasting worlds. Unicode: U+2653.",

  // ── WEATHER & NATURE ────────────────────────────────────────────────────────

  "sun": "The sun symbol (☀) represents clear, sunny weather in meteorological icons, solar energy branding, and daylight mode switches in apps and operating systems. In Unicode it is 'Black Sun with Rays', a glyph with origins in ancient solar symbolism used across cultures for thousands of years. Mobile weather apps, light/dark mode toggles, and seasonal greeting cards all reach for ☀ as the universally recognised sunny-day icon. Unicode: U+2600, HTML: &#9728;.",

  "cloud": "The cloud symbol (☁) represents overcast or cloudy weather in forecast icons and has become a metaphorical symbol for cloud computing — the infrastructure 'somewhere in the sky' powering modern software. Weather apps universally display ☁ for cloud coverage, and technology branding frequently uses stylised versions. Unicode: U+2601, HTML: &#9729;.",

  "umbrella": "The umbrella symbol (☂) represents rainy weather and protection from precipitation in weather forecasts, travel apps, and outdoor event planning. Umbrellas have protected humans from both sun and rain for over four thousand years, and the symbol is immediately understood across all cultures. Digital calendars use ☂ to flag rain risk for outdoor-event entries. Unicode: U+2602, HTML: &#9730;.",

  "snowman": "The snowman symbol (☃) represents winter, snow, and the festive season in weather icons, holiday greeting cards, and seasonal social media posts. It is one of the most cheerful and universally beloved Unicode characters, evoking imagery of childhood snow days. The related emoji ⛄ (U+26C4) shows a snowman without falling snow. Unicode: U+2603, HTML: &#9731;.",

  "lightning": "The high voltage / lightning bolt symbol (⚡) represents electrical hazard, lightning storms, fast speed, and high energy across many different contexts. Electric vehicle charging points globally display ⚡ to indicate charging availability. In social media ⚡ signals something fast, exciting, or powerful, and is also associated with the Flash superhero emblem and various sports team logos. Unicode: U+26A1, HTML: &#9889;.",

  "wind": "The wind emoji (💨) represents a gust of air, fast movement, speed, and departure across digital communication. Weather apps animate it for windy conditions, and the emoji is widely used in social media to suggest quickness, invisibility, or dramatically exiting a situation. In competitive sports contexts it signals impressive speed. Unicode: U+1F4A8, HTML: &#128168;.",

  "droplet": "The water droplet (💧) represents rain, water, humidity, hydration, and — in reaction contexts — being emotionally moved to tears. Beauty and skincare brands use it to signal moisturising products; environmental campaigns deploy it for water conservation awareness; and fitness content uses it for sweat and hydration. Unicode: U+1F4A7, HTML: &#128167;.",

  "fire": "The fire emoji (🔥) is consistently one of the top ten most-used emoji globally, used to mean literally hot, figuratively trending or popular, impressive, or 'lit'. Sports highlights, music releases, food content, and social media reactions to exciting news all heavily deploy 🔥. On Snapchat it appears beside streaks to indicate consecutive days of messaging with a friend. Unicode: U+1F525.",

  "leaf": "The leaf-fluttering-in-wind emoji (🍃) represents nature, plants, the outdoors, and a sense of fresh air or organic origin. Wellness brands, tea companies, botanical accounts, and environmental campaigns all use 🍃 as a natural and organic signal. In combination with other emoji it evokes autumn foliage, spring growth, or simply the beauty of the natural world. Unicode: U+1F343, HTML: &#127811;.",

  "crescent-moon": "The crescent moon (☽) is an elegant typographic moon symbol used in night-mode icons, Islamic symbolism, Wiccan and pagan traditions, and Halloween decoration. Unlike the filled emoji crescent 🌙, ☽ is a thin, precise typographic character ideal for minimal or editorial design contexts where a full emoji would look out of place. Unicode: U+263D, HTML: &#9789;.",

  // ── TECHNICAL ───────────────────────────────────────────────────────────────

  "command": "The Command key symbol (⌘) appears on Apple Mac keyboards as the main modifier key — the Mac equivalent of the Ctrl key on Windows. Designed by Jens Eilstrup Rasmussen and introduced on the Mac keyboard in 1983 by Steve Jobs, it replaced the overused Apple logo that had been on the key. ⌘ appears in Mac application menus next to keyboard shortcuts, in Apple product documentation, and in design materials that reference Apple products. Unicode: U+2318.",

  "option-key": "The Option/Alt key symbol (⌥) appears on Apple Mac keyboards for the Option key, used to access alternate characters and form part of multi-key shortcuts. The symbol abstractly represents a branching path or splitting of flow, suggesting that the key modifies the effect of the next keystroke. ⌥ appears frequently in Mac keyboard shortcut documentation alongside ⌘ and ⇧ — for example, ⌘⌥S for a specific application action. Unicode: U+2325.",

  "shift-key": "The Shift key symbol (⇧) is used in keyboard shortcut notation across all platforms to indicate that the Shift key must be held. On Mac keyboards it appears in application menus alongside other modifier symbols. The upward hollow arrow shape intuitively suggests 'shifting' to uppercase or an alternate function. It appears constantly in developer and power-user documentation. Unicode: U+21E7.",

  "capslock": "The Caps Lock key symbol (⇪) represents the key that locks all letter input to uppercase without requiring Shift to be held. It appears in keyboard documentation and accessibility guides explaining how to type extended passages in all capitals. The upward arrow with a horizontal underline visually distinguishes it from the plain ⇧ Shift key. Unicode: U+21EA.",

  "delete-key": "The Delete (Backspace) key symbol (⌫) is used in keyboard shortcut documentation to indicate the key that erases the character immediately to the left of the cursor. On Mac keyboards, the main Delete key functions as a backspace; a separate Forward Delete key (⌦, fn+Delete) removes the character to the right. ⌫ appears in app onboarding flows and help documentation for text-editing shortcuts. Unicode: U+232B.",

  "escape": "The Escape key symbol (⎋) represents the Esc key used to cancel operations, dismiss dialog boxes, and exit full-screen mode across all major operating systems. In terminal emulators, pressing Escape sends an escape sequence — a control character that begins cursor-movement and screen-formatting commands. It appears in power-user and developer documentation for any shortcut involving the Esc key. Unicode: U+238B.",

  "enter-key": "The Return/Enter key symbol (↩) represents the key that confirms input, submits forms, inserts a line break in text editors, and executes commands in terminals. On Mac keyboards Return is the primary confirmation key, while the numeric keypad has a separate Enter key. ↩ appears constantly in keyboard shortcut documentation and app onboarding tutorials. Unicode: U+21A9.",

  "tab-key": "The Tab key symbol (⇥) represents the key that advances to the next tab stop in text editors, cycles keyboard focus between interactive elements on a web page, and inserts a tab character in code. Correct Tab navigation is fundamental to web accessibility, allowing keyboard-only users to reach all interactive controls without a mouse. Unicode: U+21E5.",

  "power": "The power button symbol (⏻) is the internationally standardised IEC 60417 icon for power on/off, combining a vertical line (1 = on) through a circle (0 = off) to visually merge the binary states. Finalised in 1973, it appears on virtually every electronic device worldwide — computers, televisions, kitchen appliances, and power strips — as well as in software shutdown menus. Its design is one of the most instantly recognised icons in existence. Unicode: U+23FB.",

  "wifi": "The circled asterisk (⊛) is a mathematical operator denoting a binary operation performed on circled elements, used in abstract algebra and various specialised notations. In everyday contexts it can serve as a decorative bullet or separator with a symmetrical, clean appearance. Note: the familiar Wi-Fi fan icon is a separate graphic glyph not encoded as a standard Unicode character. Unicode: U+229B.",

  "gear": "The gear (cog) symbol (⚙) is the universal metaphor for settings, configuration, and mechanical systems, appearing in virtually every operating system's preferences panel and in thousands of consumer and professional apps worldwide. The gear metaphor for 'settings' was established in early graphical user interface design and has become one of the most stable, cross-cultural UI conventions. Unicode: U+2699.",

  "warning": "The warning sign (⚠) is a universal hazard indicator — an exclamation mark inside a triangle — used on road signs, electrical equipment, chemical labels, and software alert dialogs globally. The ISO 7010 W001 standard ensures the symbol is recognised internationally without accompanying text. Many software frameworks and design systems display ⚠ for non-critical warnings that require user attention but do not block progress. Unicode: U+26A0.",

  "prohibited": "The no-entry / prohibited sign (⛔) combines a red circle with a horizontal white bar, universally understood as 'do not enter' or 'this action is not allowed'. It is used on road signs, in operating system permission dialogs, and as a UI indicator that a control is disabled or an action is blocked. As an emoji it expresses refusal, boundaries, or 'no'. Unicode: U+26D4.",

  "recycling": "The universal recycling symbol (♻) is the three-arrow Möbius-loop icon designed in 1970 by Gary Anderson for the first US Earth Day. It appears on recyclable packaging, environmental campaign materials, and sustainability branding across the world. In digital contexts it is used to indicate refresh, reload, or an eco-friendly characteristic of a product or service. Unicode: U+267B.",

  "at-sign": "The at sign (@) — called 'commercial at', 'snail', 'monkey tail', or 'arobase' in different languages — originated as an abbreviation for 'at the rate of' on commercial invoices and bills of lading. Ray Tomlinson chose @ to separate usernames from hostnames in the first email address in 1971, a decision that permanently tied the symbol to internet communication. Today it is also the universal mention prefix on Twitter/X, Instagram, LinkedIn, and virtually all social platforms. Unicode: U+0040.",

  "hash": "The hash or number sign (#) has roots as a shorthand for 'pound weight' (the 'lb' abbreviation stylised) and 'number' in commerce. In programming it marks comments (Python, Ruby), preprocessor directives (C, C++), and variable interpolation in shell scripts. Twitter's adoption of hashtags (#topic) for topic categorisation in 2007 turned # into a global cultural symbol that is now universal across all social media platforms. Unicode: U+0023.",

  // ── SUPERSCRIPT & SUBSCRIPT ─────────────────────────────────────────────────

  "super-0": "Superscript zero (⁰) is a raised digit used in mathematical notation where x⁰ = 1 for all non-zero x — a foundational rule of exponents. It also appears as a footnote marker and in ordinal suffixes in some European languages. In chemistry, the superscript zero denotes a neutral (uncharged) atom or molecule. Unicode: U+2070, HTML: &#8304;.",

  "super-1": "Superscript one (¹) appears in first-power expressions (x¹ = x), as a footnote reference marker, and in ordinal suffixes like 1ˢᵗ. It is one of three superscript numerals (¹ ² ³) encoded directly in Latin-1 for historical computing compatibility reasons. Press Alt+0185 on Windows to type it.",

  "super-2": "Superscript two (²) denotes squaring a number (5² = 25), appears in area measurements (m², ft², km²), and marks ion charges in chemistry. It is the most practically encountered superscript character, appearing in Einstein's famous equation E = mc² and in everyday descriptions of floor space and surface area. Windows: Alt+0178.",

  "super-3": "Superscript three (³) denotes cubing a number (2³ = 8) and appears in volume measurements (cm³, m³, in³). Together with ² it covers the most common exponent-notation needs in everyday scientific, engineering, and culinary writing. Windows: Alt+0179.",

  "super-4": "Superscript four (⁴) raises a number to the fourth power and appears in physics (the Stefan-Boltzmann radiation law involves T⁴) and in fourth-degree polynomial expressions. It is less commonly needed than ² or ³ but essential for accurate scientific notation. Unicode: U+2074, HTML: &#8308;.",

  "super-n": "Superscript n (ⁿ) is a raised variable exponent used wherever n can represent any integer — binomial expansions (a+b)ⁿ, geometric series, and algorithm complexity O(nⁿ). It encodes a placeholder that the reader substitutes with the specific value from context. Unicode: U+207F.",

  "super-plus": "Superscript plus (⁺) denotes a positively charged ion in chemistry — Na⁺ is the sodium cation, Ca²⁺ is the calcium ion. In music notation it marks an augmented chord (C⁺). In mathematics it can indicate the set of positive numbers. Unicode: U+207A, HTML: &#8314;.",

  "super-minus": "Superscript minus (⁻) denotes a negatively charged ion in chemistry — Cl⁻ is the chloride anion, OH⁻ is the hydroxide ion. It also encodes negative exponents in scientific notation (10⁻³ = 0.001) and the inverse operation (f⁻¹ is the inverse function of f). Unicode: U+207B, HTML: &#8315;.",

  "sub-0": "Subscript zero (₀) labels the zeroth or initial element in a sequence (a₀), baseline or initial values in physics (T₀ = initial temperature, v₀ = initial velocity), and the zeroth-generation item in a series. It is common in signal processing, control theory, and thermodynamics. Unicode: U+2080.",

  "sub-1": "Subscript one (₁) labels the first element in an indexed sequence (x₁, a₁), the first atom in a molecular formula, or the first hydrogen spectral line. In telecommunications H₁ and H₂ distinguish antenna polarisation states. Unicode: U+2081.",

  "sub-2": "Subscript two (₂) is the most practically important subscript character for chemistry: H₂O (water), CO₂ (carbon dioxide), O₂ (oxygen), H₂SO₄ (sulphuric acid). It appears in millions of chemistry textbook pages, lab reports, and scientific papers. Unicode: U+2082.",

  "sub-n": "Subscript n (ₙ) is a variable subscript used in sequences (aₙ, xₙ), recurrence relations (Fₙ = Fₙ₋₁ + Fₙ₋₂ for Fibonacci numbers), and general-case formulas where the index ranges over all positive integers. Unicode: U+2099.",

  // ── UI & INTERFACE ──────────────────────────────────────────────────────────

  "info": "The information symbol (ℹ) is the globally recognised 'help' or 'about' icon — a lowercase italic letter i — used in tooltip triggers, info buttons, help overlays, and public signage. Airports, museums, transit systems, and shopping centres worldwide display blue ℹ signs to direct visitors to information desks. In software it typically appears as a white 'i' inside a blue or grey circular badge. Unicode: U+2139.",

  "checkmark-ui": "The white heavy check mark (✅) is a green-background emoji check that signals success, approval, completion, and correctness in digital communication. It is heavily used in task management apps, social media checklists, and product marketing to indicate included features. Unlike the plain text ✓, ✅ renders as a full-colour green badge on all modern emoji-capable devices. Unicode: U+2705.",

  "cross-ui": "The red cross mark (❌) is an emoji-rendered symbol for 'no', 'wrong', 'failed', or 'delete' in notifications, feedback, and social media. Its vivid red colour on modern platforms makes it immediately eye-catching as a negative signal or error indicator. Unlike the plain ✗ character, ❌ renders with full colour on emoji-capable devices. Unicode: U+274C.",

  "star-ui": "The yellow star (⭐) is a five-pointed golden star emoji used for ratings, achievement badges, and 'featured' highlights in digital products. Its warm gold colour suggests quality and premium status. App stores on iOS, Android, and the web display ⭐ ratings prominently. Unlike the plain typographic ★, ⭐ renders in full colour on emoji-capable devices. Unicode: U+2B50.",

  "heart-ui": "The heavy black heart (❤) renders as a vivid red heart emoji on modern devices and is consistently one of the top five most-used emoji globally. It is the core symbol of love, affection, and 'like' reactions across social platforms worldwide. Unlike the typographic ♥, ❤ triggers the full-colour red heart rendering in all major messaging apps and social networks. Unicode: U+2764.",

  "search": "The magnifying glass pointing left (🔍) is the universal icon for search and find functionality, appearing in search bars, find-and-replace dialogs, and explore sections across virtually every app and website in the world. Its intuitive shape communicates the action so clearly that no text label is needed, even across language barriers. Unicode: U+1F50D.",

  "lock": "The locked padlock (🔒) is the standard icon for security, encryption, password protection, and private content across all digital platforms. HTTPS-secured websites display a padlock in the browser's address bar to indicate an encrypted connection. In messaging apps 🔒 indicates end-to-end encrypted conversations. Unicode: U+1F512.",

  "unlock": "The unlocked padlock (🔓) signals that content is accessible, public, editable, or not encrypted — the counterpart to 🔒. A broken or open padlock icon in a browser indicates an insecure HTTP connection. In content management systems and file management UIs 🔓 indicates a record is available for editing. Unicode: U+1F513.",

  "bell": "The bell (🔔) is the universally understood notification and alert icon, used in app notification centres, browser permission requests, and website subscribe buttons. Social media platforms display a 🔔 in settings to manage which notifications the user receives. The 'hit the bell' call to action on YouTube channels specifically refers to this icon. Unicode: U+1F514.",

  "envelope": "The envelope (✉) is the definitive email and message icon, used on email client send buttons, contact forms, newsletter signup prompts, and social media profile links. Its simplicity transcends language barriers — the envelope shape is understood as 'send a message' in every culture. Unicode: U+2709.",

  "phone": "The telephone receiver (☎) is the classic 'call' icon, depicting a 1960s-era corded handset that remains the globally understood symbol for telephone communication despite the near-total disappearance of such devices from everyday life. It appears on international wayfinding signs, business cards, and contact forms because its meaning has been deeply culturally encoded across generations. Unicode: U+260E.",

  "home": "The house symbol (⌂) represents a home page, home button, or physical home address in interface design and wayfinding signage. Early graphical browsers displayed a house icon to return to the home page, establishing a convention still seen today in navigation bars and website headers. Unicode: U+2302.",

  "play": "The play button triangle (▶) is one of the most globally recognised interface symbols, indicating start, play, and begin in media players, game controllers, and presentation software. The triangular pointer shape intuitively suggests 'go forward'. Media control icons (▶ ⏸ ⏹ ⏭) are universally understood across languages without any text label. Unicode: U+25B6.",

  "pause": "The pause button (⏸) — two vertical parallel bars — signals a temporary, resumable halt of media playback, clearly distinguishable from the full stop (⏹) by the implication that play will continue when unpaused. It is used in music players, video editors, podcast apps, audiobooks, and automated process-control systems. Unicode: U+23F8.",
};
